"use client";

import { loadFont } from "@remotion/google-fonts/InterTight";
import { type ReactNode, useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  spring,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround, gshParams } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  BEAT,
  DEFAULT_LINES,
  FIRST_HOLD,
  type FocusPanTextElementId,
  focusPanTextTimeline,
  holdOf,
  linesOf,
  wordsOf,
} from "./timeline";

const inter = loadFont("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});

export interface FocusPanTextProps {
  lines?: string[];
  accentWord?: string;
  meta?: string;
  accent?: string;
  ink?: string;
  theme?: "dark" | "light";
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
  firstHold?: number;
  /** Frames between the payoff line's words rising. */
  stagger?: number;
  /** Weight of the lines. */
  fontWeight?: number;
  /** Solid fill in place of the gradient ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the lines. Load it yourself; Inter Tight by default. */
  fontFamily?: string;
  /** Size of the text plane, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  /**
   * Moves, trims or stretches the push, the focus moves, the payoff's words,
   * the accent and the meta row, by the ids in `./timeline`. Frames on the
   * scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<FocusPanTextElementId>;
}

const LIGHT_GROUND: Partial<GradientParams> = {
  kind: "mist",
  background: "#efeeeb",
  colors: ["#ffffff", "#f5f4f1", "#dfe0e6", "#c3c8d6"],
  blur: 0.8,
  warp: 0.3,
  seed: 5,
  grain: 0.16,
};

const THEMES = {
  dark: {
    ink: "#f2f1f6",
    muted: "rgba(242,241,246,0.5)",
    accent: "#7c90ff",
    ground: "europa" as GshPresetId | undefined,
    groundParams: undefined as Partial<GradientParams> | undefined,
    groundOffset: 6,
    scrim: "3,5,10",
    scrimAlpha: 0.5,
  },
  light: {
    ink: "#141418",
    muted: "rgba(20,20,24,0.46)",
    accent: "#3B5BFD",
    ground: undefined as GshPresetId | undefined,
    groundParams: LIGHT_GROUND as Partial<GradientParams> | undefined,
    groundOffset: 3,
    scrim: "248,247,244",
    scrimAlpha: 0.4,
  },
};

const TRACK = -0.022;
const FONT_PX = 200;
const MOVE = Easing.bezier(0.65, 0, 0.35, 1);
const TYPE_IN = Easing.bezier(0.32, 0.72, 0, 1);
const COLOR = Easing.bezier(0.83, 0, 0.17, 1);
const PUSH = Easing.bezier(0.33, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

export const focusPanTextLength = (
  lines: string[] = DEFAULT_LINES,
  firstHold = FIRST_HOLD,
) => {
  let t = 0;
  for (let i = 0; i < lines.length - 1; i++) t += holdOf(i, firstHold);
  return t + BEAT.payoffMove + BEAT.meta + BEAT.hold;
};

function buildMeasure(
  _version: number,
  fontFamily: string,
  fontWeight: number,
): (s: string) => number {
  const ctx = document.createElement("canvas").getContext("2d");
  const cache: Record<string, number> = {};
  return (s: string) => {
    if (cache[s] === undefined) {
      if (!ctx) return s.length * 0.5;
      ctx.font = `${fontWeight} ${FONT_PX}px "${fontFamily}"`;
      cache[s] =
        ctx.measureText(s).width / FONT_PX + TRACK * Array.from(s).length;
    }
    return cache[s];
  };
}

function useMeasure(fontFamily: string, fontWeight: number) {
  const [version, setVersion] = useState(0);
  const [handle] = useState(() => delayRender("focus-pan-text: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const bump = () => {
      if (live) setVersion((v) => v + 1);
    };
    document.fonts.addEventListener("loadingdone", bump);
    Promise.all([
      inter.waitUntilDone(),
      document.fonts.load(`${fontWeight} ${FONT_PX}px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        bump();
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
      document.fonts.removeEventListener("loadingdone", bump);
    };
  }, [handle, fontFamily, fontWeight]);
  return useMemo(
    () => buildMeasure(version, fontFamily, fontWeight),
    [version, fontFamily, fontWeight],
  );
}

function Icon({
  size,
  color,
  children,
}: {
  size: number;
  color: string;
  children: ReactNode;
}) {
  return (
    <svg
      viewBox="0 0 24 24"
      width={size}
      height={size}
      fill="none"
      stroke={color}
      strokeWidth={1.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{ display: "block", flexShrink: 0 }}
      aria-hidden
    >
      {children}
    </svg>
  );
}

interface Row {
  words: string[];
  line: number;
  first: number;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function FocusPanText(props: FocusPanTextProps) {
  const {
    lines = DEFAULT_LINES,
    accentWord,
    meta = "Just now",
    accent,
    ink,
    theme = "dark",
    ground,
    groundParams,
    fontWeight = 400,
    background,
    fontFamily = inter.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    timing,
  } = props;
  const frame = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    focusPanTextTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const c = THEMES[theme];
  const inkC = ink ?? c.ink;
  const hi = accent ?? c.accent;
  const preset = ground ?? (groundParams ? undefined : c.ground);
  const gParams = groundParams ?? (ground ? undefined : c.groundParams);
  const bg = gshParams(preset, gParams).background;
  const portrait = H > W * 1.1;
  const u = Math.min(W, H) / 720;
  const m = useMeasure(fontFamily, fontWeight);

  const safeLines = linesOf(lines);
  const last = safeLines.length - 1;
  const widest = m ? Math.max(...safeLines.map((l) => m(l))) : 10;
  const F = portrait ? W * 0.1 : Math.min(H * 0.16, (W * 1.12) / widest);
  const LH = F * 1.3;
  const maxW = portrait ? W * 0.86 : Number.POSITIVE_INFINITY;

  const rows = useMemo(() => {
    if (!m) return [] as Row[];
    const out: Row[] = [];
    safeLines.forEach((ln, li) => {
      const words = ln.split(/\s+/).filter(Boolean);
      let cur: string[] = [];
      let first = 0;
      words.forEach((w, wi) => {
        const next = [...cur, w].join(" ");
        if (cur.length > 0 && m(next) * F > maxW) {
          out.push({ words: cur, line: li, first });
          cur = [w];
          first = wi;
        } else {
          cur.push(w);
        }
      });
      if (cur.length) out.push({ words: cur, line: li, first });
    });
    return out;
  }, [m, safeLines, F, maxW]);

  const lineCenter = (li: number) => {
    const idx = rows
      .map((r, i) => (r.line === li ? i : -1))
      .filter((i) => i >= 0);
    if (!idx.length) return li;
    return (idx[0] + idx[idx.length - 1]) / 2;
  };

  const moves = useMemo(() => {
    const out: { at: number; len: number; line: number }[] = [];
    for (let i = 1; i <= last; i++) {
      const e = tl.get(i === last ? "payoff" : `move:${i}`);
      out.push({ at: e.start, len: e.length, line: i });
    }
    return out;
  }, [last, tl]);
  const payoff = tl.get("payoff");
  const payoffAt = payoff.start;
  const pushEl = tl.get("push");
  const accentEl = tl.get("accent");
  const metaEl = tl.get("meta");

  if (!m || rows.length === 0) {
    return (
      <AbsoluteFill
        style={{
          background:
            background === undefined
              ? bg
              : background === "transparent"
                ? undefined
                : background,
        }}
      />
    );
  }

  const focusAt = (t: number) => {
    let f = lineCenter(0);
    for (const mv of moves) {
      const from = f;
      const to = lineCenter(mv.line) + (mv.line === last ? 0.24 : 0);
      let p: number;
      if (mv.line === last) {
        p = spring({
          frame: t - mv.at,
          fps,
          config: { mass: 1, damping: 26, stiffness: 120 },
          durationInFrames: mv.len,
        });
      } else {
        p = MOVE(Math.min(1, Math.max(0, (t - mv.at) / mv.len)));
      }
      f = from + (to - from) * p;
    }
    return f;
  };
  const f = focusAt(frame);
  const fRest = focusAt(pushEl.end);
  const vel = Math.abs(f - focusAt(frame - 1));
  const motionBlur = Math.min(4 * u, vel * 9 * u);

  const settle = interpolate(
    frame,
    [payoffAt, payoffAt + payoff.beat("settle")],
    [0, 1],
    {
      ...CLAMP,
      easing: MOVE,
    },
  );
  const push = interpolate(frame, [pushEl.start, pushEl.end], [0, 1], {
    ...CLAMP,
    easing: PUSH,
  });
  const rx = 14 - 6 * settle;
  const ry = 16 - 7 * settle;
  const rz = -2.4 + 1.2 * settle;
  const panOf = (at: number) => -(at / Math.max(1, rows.length - 1)) * F * 0.28;
  // Layout rounds a baseline to whole pixels, so text panned by `left`/`top`
  // clicks along as the focus eases in. The block is laid out where the focus
  // comes to rest and the pan is a transform on top.
  const panDx = panOf(f) - panOf(fRest);
  const panDy = -(f - fRest) * LH;
  const pan =
    Math.abs(panDx) < 1e-3 && Math.abs(panDy) < 1e-3
      ? undefined
      : `translate(${panDx}px, ${panDy}px)`;
  const hinge = W * (portrait ? 0.1 : 0.085);
  const zoom = 1 + 0.045 * push;

  const payoffWords = wordsOf(safeLines[last]);
  const accentIdx = (() => {
    if (accentWord) {
      const i = payoffWords.findIndex((w) =>
        w.toLowerCase().startsWith(accentWord.toLowerCase()),
      );
      if (i >= 0) return i;
    }
    return payoffWords.length - 1;
  })();
  const colorHit = interpolate(frame, [accentEl.start, accentEl.end], [0, 1], {
    ...CLAMP,
    easing: COLOR,
  });
  // Counted from the payoff, then the offset, as the springs always were.
  const accentPunch = spring({
    frame: frame - payoffAt - (accentEl.start - payoffAt),
    fps,
    config: { mass: 0.5, damping: 12, stiffness: 200 },
  });
  const metaIn = spring({
    frame: frame - payoffAt - (metaEl.start - payoffAt),
    fps,
    config: { mass: 0.8, damping: 18, stiffness: 160 },
  });

  const mix = (a: string, b: string, t: number) =>
    t <= 0 ? a : t >= 1 ? b : `color-mix(in oklab, ${b} ${t * 100}%, ${a})`;

  const lastRowIdx = rows.length - 1;
  const metaSize = F * 0.44;

  const renderPlane = (key: string) => (
    <AbsoluteFill
      key={key}
      style={{ perspective: `${(portrait ? 1500 : 1100) * u}px` }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          transformStyle: "preserve-3d",
          transformOrigin: `${hinge}px 50%`,
          transform: `scale(${zoom}) rotateZ(${rz}deg) rotateY(${ry}deg) rotateX(${rx}deg)`,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: hinge + panOf(fRest),
            top: H * 0.5 - (fRest + 0.5) * LH,
            transform: pan,
            fontFamily,
            fontWeight,
            fontSize: F,
            lineHeight: `${LH}px`,
            letterSpacing: `${TRACK}em`,
            color: inkC,
            whiteSpace: "nowrap",
          }}
        >
          {rows.map((r, ri) => {
            const isPayoff = r.line === last;
            const dist = Math.abs(ri - f);
            const fade = 1 - 0.3 * Math.min(1, Math.max(0, dist - 0.6) / 2);
            return (
              <div
                key={`${r.line}-${r.first}`}
                style={{ height: LH, opacity: fade }}
              >
                {r.words.map((w, wi) => {
                  const gi = r.first + wi;
                  const space = wi < r.words.length - 1 ? " " : "";
                  if (!isPayoff) {
                    return (
                      <span key={`${gi}-${w}`}>
                        {w}
                        {space}
                      </span>
                    );
                  }
                  const word = tl.get(`word:${gi}`);
                  const p = TYPE_IN(
                    Math.min(
                      1,
                      Math.max(0, (frame - word.start) / word.length),
                    ),
                  );
                  const isAccent = gi === accentIdx;
                  const punch = isAccent
                    ? 1 + 0.05 * Math.sin(Math.min(1, accentPunch) * Math.PI)
                    : 1;
                  return (
                    <span key={`${gi}-${w}`}>
                      <span
                        style={{
                          display: "inline-block",
                          opacity: p,
                          transform: `translateY(${(1 - p) * F * 0.42}px) scale(${punch})`,
                          transformOrigin: "50% 80%",
                          filter:
                            p < 1 ? `blur(${(1 - p) * 6 * u}px)` : undefined,
                          color: isAccent ? mix(inkC, hi, colorHit) : inkC,
                        }}
                      >
                        {w}
                      </span>
                      {space}
                    </span>
                  );
                })}
              </div>
            );
          })}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: metaSize * 0.9,
              marginTop: LH * 0.12,
              fontSize: metaSize,
              lineHeight: 1,
              letterSpacing: "-0.005em",
              color: c.muted,
              opacity: Math.min(1, metaIn * 1.4) * (lastRowIdx >= 0 ? 1 : 0),
              transform: `translateY(${(1 - metaIn) * metaSize * 0.9}px)`,
            }}
          >
            <span>{meta}</span>
            <Icon size={metaSize * 1.05} color={c.muted}>
              <rect x="8" y="8" width="12" height="12" rx="2.5" />
              <path d="M16 8V6.5A2.5 2.5 0 0 0 13.5 4h-7A2.5 2.5 0 0 0 4 6.5v7A2.5 2.5 0 0 0 6.5 16H8" />
            </Icon>
            <Icon size={metaSize * 1.05} color={c.muted}>
              <path d="M7 11v9H4.5A1.5 1.5 0 0 1 3 18.5v-6A1.5 1.5 0 0 1 4.5 11H7Z" />
              <path d="M7 11l3.6-7.2A2 2 0 0 1 14.4 5l-.6 4h5a2 2 0 0 1 2 2.3l-1.2 7A2 2 0 0 1 17.6 20H7" />
            </Icon>
            <Icon size={metaSize * 1.05} color={c.muted}>
              <circle cx="5" cy="12" r="0.6" />
              <circle cx="12" cy="12" r="0.6" />
              <circle cx="19" cy="12" r="0.6" />
            </Icon>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );

  const band = portrait ? [36, 44, 56, 64] : [28, 40, 60, 72];
  const sharpMask = `linear-gradient(178deg, transparent ${band[0]}%, #000 ${band[1]}%, #000 ${band[2]}%, transparent ${band[3]}%)`;
  const softMask = `linear-gradient(178deg, rgba(0,0,0,0.45) 0%, #000 ${band[0]}%, transparent ${band[1]}%, transparent ${band[2]}%, #000 ${band[3]}%, rgba(0,0,0,0.45) 100%)`;
  const vBlur = motionBlur > 0.1 ? `blur(${motionBlur}px)` : "";

  return (
    <AbsoluteFill
      style={{
        background:
          background === undefined
            ? bg
            : background === "transparent"
              ? undefined
              : background,
        overflow: "hidden",
      }}
    >
      {background === undefined ? (
        <>
          <GshGround
            preset={preset}
            params={gParams}
            timeOffset={c.groundOffset}
            timeScale={0.5}
          />
          <AbsoluteFill
            style={{
              background: `radial-gradient(${portrait ? "95% 55%" : "75% 70%"} at 42% 50%, rgba(${c.scrim},${c.scrimAlpha}) 0%, rgba(${c.scrim},0) 100%)`,
            }}
          />
        </>
      ) : null}
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            filter: `blur(${7 * u + motionBlur}px)`,
            WebkitMaskImage: softMask,
            maskImage: softMask,
          }}
        >
          {renderPlane("soft")}
        </AbsoluteFill>
        <AbsoluteFill
          style={{
            filter: vBlur || undefined,
            WebkitMaskImage: sharpMask,
            maskImage: sharpMask,
          }}
        >
          {renderPlane("sharp")}
        </AbsoluteFill>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

export default FocusPanText;

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The slow push on the text plane, the focus moving down the lines one by
// one, landing on the payoff line, the payoff's words rising, the accent word
// lighting up and the meta row under it. Frames on the 30 fps scene
// timeline, after `delay` and `speed`. The ids are public: a saved `timing`
// prop refers to them.

export type FocusPanTextElementId =
  | "push"
  | `move:${number}`
  | "payoff"
  | `word:${number}`
  | "accent"
  | "meta";

export interface FocusPanTextTimingProps {
  lines?: string[];
  firstHold?: number;
  stagger?: number;
}

export const BEAT = {
  decay: 0.8,
  minHold: 18,
  move: 14,
  payoffMove: 24,
  wordIn: 12,
  wordStagger: 3,
  accent: 20,
  color: 10,
  meta: 24,
  hold: 48,
  settle: 40,
};

export const DEFAULT_LINES = [
  "The security scan is clean.",
  "All 48 checks passed.",
  "Your domain is live.",
  "You're ready to launch.",
];
export const FIRST_HOLD = 30;

/** Frames line `i` holds the focus before it moves on. */
export const holdOf = (i: number, first: number) =>
  Math.max(BEAT.minHold, Math.round(first * BEAT.decay ** i));

/** The lines shown: the defaults when the list is empty. */
export const linesOf = (lines: string[]) =>
  lines.length > 0 ? lines : DEFAULT_LINES;

export const wordsOf = (line: string) => line.split(/\s+/).filter(Boolean);

// `push` is the camera's push over the whole scene, to the frame the focus
// rests on. `move:<i>` is the focus moving onto line `i`, `payoff` onto the
// last line (a spring; the plane settles over `settle`). `word:<k>` is the
// payoff's word `k` rising. The moves, then the words, form a chain;
// `accent` and `meta` follow the payoff.
export const focusPanTextTimeline = defineTimeline<
  FocusPanTextElementId,
  FocusPanTextTimingProps
>(
  ({
    lines = DEFAULT_LINES,
    firstHold = FIRST_HOLD,
    stagger = BEAT.wordStagger,
  }) => {
    const safeLines = linesOf(lines);
    const last = safeLines.length - 1;
    const moves: { at: number; line: number }[] = [];
    let t = 0;
    for (let i = 1; i <= last; i++) {
      t += holdOf(i - 1, firstHold);
      moves.push({ at: t, line: i });
    }
    const payoffAt = moves.length ? moves[moves.length - 1].at : 0;
    const before = last > 1 ? (`move:${last - 1}` as const) : undefined;

    const elements: TimelineElement<FocusPanTextElementId>[] = [
      {
        id: "push",
        lane: "Camera",
        label: "push",
        start: 0,
        length: payoffAt + BEAT.payoffMove + BEAT.meta + BEAT.hold,
      },
    ];
    for (const mv of moves.slice(0, -1)) {
      elements.push({
        id: `move:${mv.line}`,
        lane: "Focus",
        label: safeLines[mv.line],
        start: mv.at,
        length: BEAT.move,
        follows: mv.line > 1 ? `move:${mv.line - 1}` : undefined,
      });
    }
    elements.push({
      id: "payoff",
      lane: "Focus",
      label: safeLines[last],
      start: payoffAt,
      length: BEAT.payoffMove,
      follows: before,
      beats: { settle: BEAT.settle },
    });
    wordsOf(safeLines[last]).forEach((w, k) => {
      elements.push({
        id: `word:${k}`,
        lane: "Payoff",
        label: w,
        start: payoffAt + k * stagger,
        length: BEAT.wordIn,
        follows: k > 0 ? `word:${k - 1}` : before,
      });
    });
    elements.push(
      {
        id: "accent",
        lane: "Accent",
        label: "accent",
        start: payoffAt + BEAT.accent,
        length: BEAT.color,
        follows: "payoff",
      },
      {
        id: "meta",
        lane: "Meta",
        label: "meta",
        start: payoffAt + BEAT.meta,
        length: BEAT.hold,
        follows: "payoff",
      },
    );
    return elements.sort((a, b) => a.start - b.start);
  },
);
